solution.solution.cpp:
void setToZero(int* p)
{
    if (p != nullptr)
    {
        *p = 0;
    }
}

int valueOr(const int* p, int fallback)
{
    return p != nullptr ? *p : fallback;
}

unitTests:
TEST("setToZero changes the target") { int score{ 99 }; setToZero(&score); CHECK_EQ(score, 0); }
TEST("setToZero ignores nullptr") { setToZero(nullptr); CHECK(true); }
TEST("valueOr reads the target") { int n{ 7 }; CHECK_EQ(valueOr(&n, -1), 7); }
TEST("valueOr falls back on nullptr") { CHECK_EQ(valueOr(nullptr, -1), -1); }

